INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(41111, 'Judges 5:23', 'Judges', 5, 23, 'د څښتن فرښته وایي: په میروز باندې لعنت ووایئ د هغه ځای په اوسېدونکو سخت لعنت ووایئ ځکه چې دوی د څښتن مرستې ته راغلي نه دي چې کومک وکړي د څښتن سره مقابله کې د قوي جنګیالو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_23.mp3', '', 1761754199, 1761754199),
(41112, 'Judges 5:24', 'Judges', 5, 24, 'یاعیل ده ډېره بختوره چې ده ښځه د حابر قیني زیات برکت دې هغه ومومي تر ټولو ښځو چې په خېمو کې اوسي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_24.mp3', '', 1761754199, 1761754199),
(41113, 'Judges 5:25', 'Judges', 5, 25, 'سیسرا وغوښتې اوبه خو هغې ورکړې شیدې په شاهانه جام کې یې ورکړې شړومبې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_25.mp3', '', 1761754199, 1761754199),
(41114, 'Judges 5:26', 'Judges', 5, 26, 'هغې واخیست په یو لاس کې د خېمې موږی او په بل لاس کې یې څټک د مزدور هغې وواهه سیسرا او کړه ورماته یې کوپړۍ او شقیقه یې کړه سورۍ د هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_26.mp3', '', 1761754199, 1761754199),
(41115, 'Judges 5:27', 'Judges', 5, 27, 'سیسرا ولوېدلو پښو ته د هغې هغه وغورځېد او پروت ؤ هلته هغه وغورځېده پښو ته د هغې او ولوېد هغه په ځمکه باندې مړ پرېوت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_27.mp3', '', 1761754199, 1761754199),
(41116, 'Judges 5:28', 'Judges', 5, 28, 'د کړکۍ نه د سیسرا مور وکتل په ځیر ځیر یې د جالۍ له شا کتل هغې وکړله پوښتنه: ولې ځنډ وکړ په راتللو کې جنګي ګاډۍ د هغه؟ ولې نه اورو اواز د ګاډۍ د ارابو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_28.mp3', '', 1761754199, 1761754199),
(41117, 'Judges 5:29', 'Judges', 5, 29, 'پوهه ملګرې د هغې ورته ځواب ورکوي تکراروي هغه د ځان سره دا خبرې:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_29.mp3', '', 1761754199, 1761754199),
(41118, 'Judges 5:30', 'Judges', 5, 30, 'هغوی نیولی غنیمت او هغه وېشي سره یوه انجلۍ یا دوه نجونې هر عسکر دپاره رنګین لباس د سیسرا دپاره ګلدوزي شوې ټوټې زما غاړې ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_30.mp3', '', 1761754199, 1761754199),
(41119, 'Judges 5:31', 'Judges', 5, 31, 'ای څښتنه! دښمنان دې ستا هلاک شي د سیسرا په ډول ټول خو دوستان دې ستا ځلیږي د روښانه لمر په شان له هغې وروسته په هغه خاوره کې څلوېښت کاله ارامي وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges5_verse_31.mp3', '', 1761754199, 1761754199),
(41120, 'Exodus 24:1', 'Exodus', 24, 1, 'څښتن موسی ته وویل: «ته، هارون، ناداب، ابیهو او د اسراییلو اویا مشران ماته غره ته راوخېژئ او د لېرې فاصلې څخه راته سجده وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus24_verse_1.mp3', '', 1761754199, 1761754199),
(41121, 'Exodus 24:2', 'Exodus', 24, 2, 'یوازې ته ماته نژدې راشه او نور دې راته نژدې نه راځي. د اسراییلو د قوم د نورو خلکو څخه دې هېڅوک هم غره ته نه راخېژي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus24_verse_2.mp3', '', 1761754199, 1761754199),
(41122, 'Exodus 24:3', 'Exodus', 24, 3, 'کله چې موسی راغی او خلکو ته یې د څښتن ټولې خبرې او قوانین اعلان کړل، هغوی په یو اواز په ځواب کې وویل: «مونږ به د څښتن په هره خبره باندې عمل کوو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus24_verse_3.mp3', '', 1761754199, 1761754199),
(41123, 'Exodus 24:4', 'Exodus', 24, 4, 'موسی د څښتن ټول حکمونه ولیکل. هغه سهار وختي پاڅېد او د غره په لمنه کې یې د قربانۍ ځای جوړ کړ او هلته یې دولس تیږې چې د اسراییلو د دولسو قبیلو استازیتوب یې کاوه، ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus24_verse_4.mp3', '', 1761754199, 1761754199),
(41124, 'Exodus 24:5', 'Exodus', 24, 5, 'بیا موسی ځینې اسراییلي ځوانان ولېږل او هغوی سوځېدونکې نذرانې او ځینې غویان د سلامتۍ د نذرانې په توګه څښتن ته قرباني کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus24_verse_5.mp3', '', 1761754199, 1761754199),
(41125, 'Exodus 24:6', 'Exodus', 24, 6, 'موسی نیمه وینه راواخیستله او په لګنونو کې یې واچوله او نیمه یې د قربانۍ په ځای باندې وشیندله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus24_verse_6.mp3', '', 1761754199, 1761754199),
(41126, 'Exodus 24:7', 'Exodus', 24, 7, 'بیا هغه د لوظ کتاب راواخیست او خلکو ته یې په لوړ اواز سره ولوست. هغوی وویل: «مونږ به د څښتن اطاعت کوو او د هغه په ټولو امرونو باندې به عمل کوو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus24_verse_7.mp3', '', 1761754199, 1761754199),
(41127, 'Exodus 24:8', 'Exodus', 24, 8, 'بیا موسی هغه وینه چې په لګنونو کې وه، راواخیستله او په خلکو باندې یې وشیندله. هغه وویل: «دا د هغه لوظ وینه ده چې څښتن د دغو ټولو حکمونو له مخې تاسو سره کړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus24_verse_8.mp3', '', 1761754199, 1761754199),
(41128, 'Exodus 24:9', 'Exodus', 24, 9, 'موسی د هارون، ناداب، ابیهو او د اسراییلو د اویا مشرانو سره غره ته وخوت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus24_verse_9.mp3', '', 1761754199, 1761754199),
(41129, 'Exodus 24:10', 'Exodus', 24, 10, 'او د اسراییلو خدای یې ولیده. د هغه د پښو لاندې د لاجوردو د فرش په شان یو څه ښکاره کېدل چې د اسمان په شان شنه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus24_verse_10.mp3', '', 1761754199, 1761754199),
(41130, 'Exodus 24:11', 'Exodus', 24, 11, 'که څه هم د اسراییلو دغو مشرانو خدای ولیده، خو هغه ورته زیان ونه رساوه. بیا هغوی وخوړل او ویې څښل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus24_verse_11.mp3', '', 1761754199, 1761754199),
(41131, 'Exodus 24:12', 'Exodus', 24, 12, 'څښتن موسی ته وویل: «ماته د غره سرته راوخېژه او دلته پاتې شه. زه به تاته د تیږو لوحې چې په هغو باندې مې د خلکو د لارښوونې دپاره حکمونه لیکلي دي، درکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus24_verse_12.mp3', '', 1761754199, 1761754199),
(41132, 'Exodus 24:13', 'Exodus', 24, 13, 'موسی او د هغه مرستیال یعنې یوشع تیار شول او موسی سپېڅلي غره ته ورپورته شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus24_verse_13.mp3', '', 1761754199, 1761754199),
(41133, 'Exodus 24:14', 'Exodus', 24, 14, 'موسی مشرانو ته وویل: «تاسو دلته انتظار وباسئ، ترڅو مونږ بېرته راشو. هارون او حور تاسو سره دي او هرڅوک چې کومه مسئله لري، هغوی ته دې ورشي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus24_verse_14.mp3', '', 1761754199, 1761754199),
(41134, 'Exodus 24:15', 'Exodus', 24, 15, 'کله چې موسی غره ته پورته شو، نو ورېځې غر پټ کړ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus24_verse_15.mp3', '', 1761754199, 1761754199),
(41135, 'Exodus 24:16', 'Exodus', 24, 16, 'او د څښتن جلال د سینا په غره باندې خپور شو. غر شپږ ورځې په ورېځ کې پټ ؤ او په اوومه ورځ څښتن له ورېځ څخه موسی ته غږ وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus24_verse_16.mp3', '', 1761754199, 1761754199),
(41136, 'Exodus 24:17', 'Exodus', 24, 17, 'د څښتن جلال اسراییلیانو ته داسې ښکاره کېده لکه د غره په سر باندې چې اور بل وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus24_verse_17.mp3', '', 1761754199, 1761754199),
(41137, 'Exodus 24:18', 'Exodus', 24, 18, 'کله چې موسی غره ته ورپورته شو، هغه په ورېځ کې ورننوت او څلوېښت ورځې او څلوېښت شپې په غره کې پاتې شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus24_verse_18.mp3', '', 1761754199, 1761754199),
(41138, 'Numbers 31:1', 'Numbers', 31, 1, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_1.mp3', '', 1761754199, 1761754199),
(41139, 'Numbers 31:2', 'Numbers', 31, 2, '«څه چې مدیانیانو د اسراییلو د خلکو سره کړي وو، د هغه په خاطر هغوی ته سزا ورکړه. چې کله دې دا کار وکړ، بیا به ته مړ شې او د خپلو نیکونو سره به یوځای شې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_2.mp3', '', 1761754199, 1761754199),
(41140, 'Numbers 31:3', 'Numbers', 31, 3, 'بیا موسی قوم ته وویل: «د جګړې دپاره تیار شئ، ترڅو وکولای شئ چې د څښتن په امر د مدیانیانو څخه بدل واخلئ او هغوی ته سزا ورکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_3.mp3', '', 1761754199, 1761754199),
(41141, 'Numbers 31:4', 'Numbers', 31, 4, 'د اسراییلو د هرې قبیلې څخه زر تنه جنګ ته ولېږئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_4.mp3', '', 1761754199, 1761754199),
(41142, 'Numbers 31:5', 'Numbers', 31, 5, 'نو د هرې قبیلې څخه زر تنه غوره شول، ټول ۱۲۰۰۰ تنه د جګړې دپاره تیار شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_5.mp3', '', 1761754199, 1761754199),
(41143, 'Numbers 31:6', 'Numbers', 31, 6, 'موسی هغوی جګړې ته ولېږل او د العازار کاهن زوی فینحاس د هغوی سره ؤ. هغه د سپېڅلې خېمې څخه لږ سامان او سرني واخیستل چې د جګړې د اعلانولو د اشارې دپاره ووهل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_6.mp3', '', 1761754199, 1761754199),
(41144, 'Numbers 31:7', 'Numbers', 31, 7, 'څنګه چې څښتن موسی ته امر کړی ؤ، اسراییلیانو د مدیانیانو سره جګړه وکړه او د هغوی ټول نارینه یې ووژل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_7.mp3', '', 1761754199, 1761754199),
(41145, 'Numbers 31:8', 'Numbers', 31, 8, 'په هغو کې د مدیان پنځه پاچاهان یعنې اوي، راقم، صور، حور او رابع هم شامل وو. همدارنګه هغوی د بعور زوی بلعام هم وواژه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_8.mp3', '', 1761754199, 1761754199),
(41146, 'Numbers 31:9', 'Numbers', 31, 9, 'د اسراییلو خلکو د مدیانیانو ښځې او ماشومان ونیول، د هغوی ټولې پادې او رمې یې بوتللې او ټوله شتمني یې ورته لوټ کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_9.mp3', '', 1761754199, 1761754199),
(41147, 'Numbers 31:10', 'Numbers', 31, 10, 'او د هغوی ټول ښارونه او کمپونه یې وسوځول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_10.mp3', '', 1761754199, 1761754199),
(41148, 'Numbers 31:11', 'Numbers', 31, 11, 'هغه ټول غنیمت چې هغوی نیولی ؤ او په هغه کې اسیران او حیوانات هم شامل وو، واخیستل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_11.mp3', '', 1761754199, 1761754199),
(41149, 'Numbers 31:12', 'Numbers', 31, 12, 'او هغه یې موسی، العازار او د اسراییلو قوم ته هغه کمپ ته چې د موآب په ډاګونو کې د اردن د سیند په بله غاړه اریحا ته مخامخ ؤ، راوړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_12.mp3', '', 1761754199, 1761754199),
(41150, 'Numbers 31:13', 'Numbers', 31, 13, 'موسی، العازار او د قوم ټول مشران د کمپ څخه د هغوی مخې ته ورووتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_13.mp3', '', 1761754199, 1761754199),
(41151, 'Numbers 31:14', 'Numbers', 31, 14, 'موسی د لښکرو په قوماندانانو باندې چې د جګړې څخه راستانه شوي وو، په قهر شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_14.mp3', '', 1761754199, 1761754199),
(41152, 'Numbers 31:15', 'Numbers', 31, 15, 'د هغوی څخه یې پوښتنه وکړه: «تاسو ولې ټولې ښځې ژوندۍ پریښې دي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_15.mp3', '', 1761754199, 1761754199),
(41153, 'Numbers 31:16', 'Numbers', 31, 16, 'هغوی هغه څوک دي چې د بلعام په مشوره یې عمل کړی ؤ او زمونږ خلکو ته یې بلنه ورکړې وه چې د بعل فغور د خدای عبادت وکړي. ځکه څښتن مونږ ته سزا راکړه او په خپل قوم باندې یې وبا راوستله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_16.mp3', '', 1761754199, 1761754199),
(41154, 'Numbers 31:17', 'Numbers', 31, 17, 'نو اوس ټول هلکان ووژنئ او هره ښځه چې د کوم سړي سره یوځای شوې وي ووژنئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_17.mp3', '', 1761754199, 1761754199),
(41155, 'Numbers 31:18', 'Numbers', 31, 18, 'خو ټولې پېغلې نجونې ژوندۍ پرېږدئ او هغوی د خپلو ځانونو دپاره وساتئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_18.mp3', '', 1761754199, 1761754199),
(41156, 'Numbers 31:19', 'Numbers', 31, 19, 'بیا موسی جنګیالیو ته وویل: «که چېرې ستاسو څخه چا څوک وژلی وي یا مو یو مړي ته لاس وروړی وي، باید اووه ورځې د کمپ څخه دباندې پاتې شي. په درېمه او اوومه ورځ باید تاسو خپل ځانونه او هغه ښځې چې تاسو اسیرانې نیولې دي، پاکې کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_19.mp3', '', 1761754199, 1761754199),
(41157, 'Numbers 31:20', 'Numbers', 31, 20, 'همدارنګه هغه ټول کالي او ټول شیان چې د څرمنې، د وزو د وړیو او لرګیو څخه جوړ شوي وي هم پاک کړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_20.mp3', '', 1761754199, 1761754199),
(41158, 'Numbers 31:21', 'Numbers', 31, 21, 'العازار کاهن هغو کسانو ته چې د جګړې څخه راستانه شوي وو، وویل: «دا هغه مقررات دي چې څښتن موسی ته ورکړي دي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_21.mp3', '', 1761754199, 1761754199),
(41159, 'Numbers 31:22', 'Numbers', 31, 22, 'سره زر، سپین زر، برنج، اوسپنه، قلعي او سرپ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_22.mp3', '', 1761754199, 1761754199),
(41160, 'Numbers 31:23', 'Numbers', 31, 23, 'او نور ټول هغه شیان چې نه سوځي، باید په سره اور کې واچول شي او هغه به پاک شي. خو هغه هم باید د هغو اوبو په وسیله پاک شي چې د پاکوالي دپاره کارول کیږي او هغه شیان چې په اور کې سوځي باید د اوبو په وسیله پاک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_23.mp3', '', 1761754199, 1761754199),
(41161, 'Numbers 31:24', 'Numbers', 31, 24, 'په اوومه ورځ باید خپل کالي ووینځئ، بیا به په مذهبي لحاظ پاک شئ او کمپ ته د ننوتلو اجازه به ولرئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_24.mp3', '', 1761754199, 1761754199),
(41162, 'Numbers 31:25', 'Numbers', 31, 25, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_25.mp3', '', 1761754199, 1761754199),
(41163, 'Numbers 31:26', 'Numbers', 31, 26, '«باید ته او العازار د قوم د نورو مشرانو سره د اسیرانو او حیواناتو په شمول هغه ټول شیان وشمارئ چې د مدیانیانو څخه نیول شوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_26.mp3', '', 1761754199, 1761754199),
(41164, 'Numbers 31:27', 'Numbers', 31, 27, 'هغه نیول شوي شیان په دوو مساوي برخو ووېشئ، یوه برخه یې هغو جنګیالیو ته چې جګړې ته تللي وو او بله برخه یې پاتې قوم ته ورکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_27.mp3', '', 1761754199, 1761754199),
(41165, 'Numbers 31:28', 'Numbers', 31, 28, 'د هغو جنګیالیو د برخې څخه چې په جګړه کې جنګېدلي دي، د هرو پنځو سوو اسیرانو، غویانو، خرو، پسونو او یا وزو څخه یو یو څښتن ته د هغه د برخې په توګه بېل کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_28.mp3', '', 1761754199, 1761754199),
(41166, 'Numbers 31:29', 'Numbers', 31, 29, 'هغه څښتن ته د ځانګړې اعانې په توګه العازار ته ورکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_29.mp3', '', 1761754199, 1761754199),
(41167, 'Numbers 31:30', 'Numbers', 31, 30, 'د پاتې قوم د برخې څخه د هرو پنځوسو اسیرانو څخه یو او هماغه شان د پنځوسو غویانو، خرو، پسونو او وزو څخه یو یو واخلئ او هغو لاویانو ته یې ورکړئ چې د سپېڅلې خېمې مسوولان دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_30.mp3', '', 1761754199, 1761754199),
(41168, 'Numbers 31:31', 'Numbers', 31, 31, 'څښتن چې کوم حکم کړی ؤ، موسی او العازار هماغسې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_31.mp3', '', 1761754199, 1761754199),
(41169, 'Numbers 31:41', 'Numbers', 31, 41, 'نو څنګه چې څښتن حکم کړی ؤ، موسی د څښتن ټوله برخه العازار کاهن ته ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_41.mp3', '', 1761754199, 1761754199),
(41170, 'Numbers 31:47', 'Numbers', 31, 47, 'د دې برخې څخه موسی د هرو پنځوسو اسیرانو او حیواناتو څخه یو یو واخیست او هغه یې د څښتن د حکم له مخې لاویانو ته چې د سپېڅلې خېمې مسوولان وو، ورکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_47.mp3', '', 1761754199, 1761754199),
(41171, 'Numbers 31:48', 'Numbers', 31, 48, 'د لښکرو قوماندانان موسی ته ورغلل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_48.mp3', '', 1761754199, 1761754199),
(41172, 'Numbers 31:49', 'Numbers', 31, 49, 'او ورته ویې ویل: «باداره، مونږ خپلې لښکرې وشمېرلې، یو کس هم کم نه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_49.mp3', '', 1761754199, 1761754199),
(41173, 'Numbers 31:50', 'Numbers', 31, 50, 'نو مونږ د سرو زرو ګاڼې، بازوبندونه، بنګړي، ګوتې، غوږوالۍ او غاړکۍ چې مونږ هر یو نیولي دي، راوړي دي. مونږ هغه څښتن ته د خپل ژوند د بیې د ادا کولو دپاره وړاندې کوو، ترڅو هغه زمونږ ساتنه وکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_50.mp3', '', 1761754199, 1761754199),
(41174, 'Numbers 31:51', 'Numbers', 31, 51, 'موسی او العازار هغه سره زر واخیستل چې ټول د ګاڼو په شکل کې وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_51.mp3', '', 1761754199, 1761754199),
(41175, 'Numbers 31:52', 'Numbers', 31, 52, 'د قوماندانانو د ټولې اعانې وزن نژدې دوه سوه کیلو ګرامه ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_52.mp3', '', 1761754199, 1761754199),
(41176, 'Numbers 31:53', 'Numbers', 31, 53, 'په دې کې هغه شیان شامل نه وو کوم چې جنګیالیو د خپلو ځانونو دپاره ساتلي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_53.mp3', '', 1761754199, 1761754199),
(41177, 'Numbers 31:54', 'Numbers', 31, 54, 'نو موسی او العازار سره زر سپېڅلې خېمې ته راوړل، ترڅو اسراییلیان هغه د یادګار په توګه وساتي چې څښتن د هغوی سره مرسته کړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers31_verse_54.mp3', '', 1761754199, 1761754199),
(41178, 'Proverbs 19:1', 'Proverbs', 19, 1, 'هغه غریب چې خپل ژوند په صداقت تېروي له هغه چا نه ښه دی چې کم‌عقل او دروغجن وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_1.mp3', '', 1761754199, 1761754199),
(41179, 'Proverbs 19:2', 'Proverbs', 19, 2, 'له علم پرته د خپلو غوښتنو ښکاره کول ښه کار نه دی ځکه څوک چې بیړه کوي خپله لار خطا کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_2.mp3', '', 1761754199, 1761754199),
(41180, 'Proverbs 19:3', 'Proverbs', 19, 3, 'انسان په خپل جهالت ځان تباه کوي او بیا ګناه او ملامتیا په څښتن اچوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_3.mp3', '', 1761754199, 1761754199),
(41181, 'Proverbs 19:4', 'Proverbs', 19, 4, 'شتمن سړی ډېر دوستان پیدا کوي خو غریبي له انسان نه خپل ورور هم جدا کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_4.mp3', '', 1761754199, 1761754199),
(41182, 'Proverbs 19:5', 'Proverbs', 19, 5, 'دروغجن شاهد به بې‌سزا پاتې نه شي او څوک چې دروغ بادوي د سزا نه به خلاص نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_5.mp3', '', 1761754199, 1761754199),
(41183, 'Proverbs 19:6', 'Proverbs', 19, 6, 'ډېر خلک له مشرانو نه مرسته غواړي او د تحفې ورکوونکي سره هرڅوک دوستي کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_6.mp3', '', 1761754199, 1761754199),
(41184, 'Proverbs 19:7', 'Proverbs', 19, 7, 'که د غریب سړي نه ټول خپلوان کرکه کوي نو دوستان به څومره ترې ځان لېرې ساتي او حتی د خبرو کولو کوښښ یې هم ځای ته نه رسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_7.mp3', '', 1761754199, 1761754199),
(41185, 'Proverbs 19:8', 'Proverbs', 19, 8, 'څوک چې پوهه حاصلوي نو د خپل ځان سره مینه کوي بریالی دی هغه څوک چې پوهې ته په درنه سترګه ګوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_8.mp3', '', 1761754199, 1761754199),
(41186, 'Proverbs 19:9', 'Proverbs', 19, 9, 'دروغجن شاهد به بې‌سزا پاتې نه شي او څوک چې دروغ بادوي هغه به تباه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_9.mp3', '', 1761754199, 1761754199),
(41187, 'Proverbs 19:10', 'Proverbs', 19, 10, 'که د کم‌عقل سره د عیش او عشرت ژوند ښه نه ښکاري نو په شهزادګانو به د غلام حکومت کول څومره نامناسبه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_10.mp3', '', 1761754199, 1761754199),
(41188, 'Proverbs 19:11', 'Proverbs', 19, 11, 'هوښیار انسان زر نه په قهریږي او څوک چې د بل په ګناه پرده اچوي سرلوړې به شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_11.mp3', '', 1761754199, 1761754199),
(41189, 'Proverbs 19:12', 'Proverbs', 19, 12, 'د پاچا قهر د غړمبېدونکي زمري په څېر دی خو رحم یې د پرخې په شان په شنو واښو وریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_12.mp3', '', 1761754199, 1761754199),
(41190, 'Proverbs 19:13', 'Proverbs', 19, 13, 'کم‌عقل زوی د خپل پلار دپاره لوی مصیبت دی او د جګړه‌مارې ښځې جنګ د تل څڅېدونکي چت په څېر دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_13.mp3', '', 1761754199, 1761754199),
(41191, 'Proverbs 19:14', 'Proverbs', 19, 14, 'کور او مال د مور او پلار نه په میراث پاتې کیږي خو هوښیاره ښځه د څښتن له خوا ښه سوغات دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_14.mp3', '', 1761754199, 1761754199),
(41192, 'Proverbs 19:15', 'Proverbs', 19, 15, 'لټي په انسان دروند خوب راولي او ناراسته انسان وږی پاتې کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_15.mp3', '', 1761754199, 1761754199),
(41193, 'Proverbs 19:16', 'Proverbs', 19, 16, 'څوک چې د څښتن په حکمونو عمل کوي نو خپل ځان ساتي څوک چې د هغه لارو ته په سپکه سترګه ګوري نو مړ به شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_16.mp3', '', 1761754199, 1761754199),
(41194, 'Proverbs 19:17', 'Proverbs', 19, 17, 'څوک چې په غریب رحم کوي لکه څښتن ته چې پور ورکوي او څښتن به ورته د دې اجر ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_17.mp3', '', 1761754199, 1761754199),
(41195, 'Proverbs 19:18', 'Proverbs', 19, 18, 'په پوره هیلې خپل زوی ته نصیحت کوه هسې نه چې په اخر کې یې ژوند تباه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_18.mp3', '', 1761754199, 1761754199),
(41196, 'Proverbs 19:19', 'Proverbs', 19, 19, 'پرېږده چې غوسه ناک انسان د خپل قهر نتیجه وګوري. که یوځل یې د سزا نه وژغورې نو بیا به یې تل ژغورې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_19.mp3', '', 1761754199, 1761754199),
(41197, 'Proverbs 19:20', 'Proverbs', 19, 20, 'لارښوونه قبوله کړه او نصیحت واوره نو په اخر کې به د حکمت خاوند شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_20.mp3', '', 1761754199, 1761754199),
(41198, 'Proverbs 19:21', 'Proverbs', 19, 21, 'د انسان په زړه کې ډېرې نقشې وي خو هغه څه کیږي چې د څښتن خوښه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_21.mp3', '', 1761754199, 1761754199),
(41199, 'Proverbs 19:22', 'Proverbs', 19, 22, 'مینه او وفا د انسان ښکلا ده او یو غریب انسان د دروغجن نه غوره دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_22.mp3', '', 1761754199, 1761754199),
(41200, 'Proverbs 19:23', 'Proverbs', 19, 23, 'له څښتن څخه وېره انسان ته ژوند وربخښي او په مړه ګېډه شپه تېروي او د هرې بلا نه یې خوندي ساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_23.mp3', '', 1761754199, 1761754199),
(41201, 'Proverbs 19:24', 'Proverbs', 19, 24, 'لټ انسان کاسې ته لاس غزولی شي خو خپله مړۍ خولې ته وړلی نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_24.mp3', '', 1761754199, 1761754199),
(41202, 'Proverbs 19:25', 'Proverbs', 19, 25, 'ملنډې وهونکي ته په لښته سزا ورکړه چې د ساده سړي د عبرت سبب شي او که د عقل خاوند اصلاح کړې هغه به نور هم علم حاصل کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_25.mp3', '', 1761754199, 1761754199),
(41203, 'Proverbs 19:26', 'Proverbs', 19, 26, 'څوک چې په پلار لاس اوچتوي او مور له کوره شړي نو داسې زوی شرم او رسوایي راوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_26.mp3', '', 1761754199, 1761754199),
(41204, 'Proverbs 19:27', 'Proverbs', 19, 27, 'نو ای زما زویه! که ته نصیحت ته غوږ ونه نیسې نو د علم د خبرو نه به بې‌لارې شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_27.mp3', '', 1761754199, 1761754199),
(41205, 'Proverbs 19:28', 'Proverbs', 19, 28, 'بدکاره شاهد په انصاف پورې خندا کوي او بدکاران د شرارت نه خوند اخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_28.mp3', '', 1761754199, 1761754199),
(41206, 'Proverbs 19:29', 'Proverbs', 19, 29, 'د ملنډو وهونکو دپاره سزا ده او د کم‌عقلانو د ملا دپاره لښته ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs19_verse_29.mp3', '', 1761754199, 1761754199),
(41207, 'Psalms 78:1', 'Psalms', 78, 1, 'ای زما قومه، زما تعلیم ته غوږ شئ واورئ په غور زما د خولې خبرې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_1.mp3', '', 1761754199, 1761754199),
(41208, 'Psalms 78:2', 'Psalms', 78, 2, 'خبرې وبه کړمه زه په مثالونو باندې زه به رازونه کړم بیان د تېرو شویو وختو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_2.mp3', '', 1761754199, 1761754199),
(41209, 'Psalms 78:3', 'Psalms', 78, 3, 'هغه شیان چې اورېدلي او زده کړي مو دي هغه شیان چې مو نیکونو بیان کړي راته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_3.mp3', '', 1761754199, 1761754199),
(41210, 'Psalms 78:4', 'Psalms', 78, 4, 'هغه به پټ نه ساتو خپلو اولادونو څخه کړو به یې بیان راتلونکي نسل ته وړ د ستایلو کارنامې او هم قدرت د څښتن او هم کارونه عجیبه کوم چې هغه کړي دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms78_verse_4.mp3', '', 1761754199, 1761754199);